ALTER TABLE pilot_notebooks ADD CONSTRAINT pilot_notebook_lineage UNIQUE(id,check_id);
ALTER TABLE pilot_bundles ADD CONSTRAINT pilot_bundle_lineage UNIQUE(id,check_id);
ALTER TABLE pilot_bundles ADD CONSTRAINT pilot_bundle_notebook_lineage FOREIGN KEY(notebook_id,check_id) REFERENCES pilot_notebooks(id,check_id);
ALTER TABLE pilot_input_versions ADD CONSTRAINT pilot_version_lineage UNIQUE(id,bundle_id);
ALTER TABLE pilot_photo_assets ADD CONSTRAINT pilot_asset_bundle_lineage FOREIGN KEY(bundle_id,check_id) REFERENCES pilot_bundles(id,check_id);
ALTER TABLE pilot_snapshots ADD CONSTRAINT pilot_snapshot_lineage UNIQUE(id,check_id);
ALTER TABLE pilot_jobs ADD CONSTRAINT pilot_job_bundle_lineage FOREIGN KEY(bundle_id,check_id) REFERENCES pilot_bundles(id,check_id);
ALTER TABLE pilot_jobs ADD CONSTRAINT pilot_job_input_lineage FOREIGN KEY(input_version_id,bundle_id) REFERENCES pilot_input_versions(id,bundle_id);
ALTER TABLE pilot_jobs ADD CONSTRAINT pilot_job_snapshot_lineage FOREIGN KEY(snapshot_id,check_id) REFERENCES pilot_snapshots(id,check_id);
ALTER TABLE pilot_jobs ADD CONSTRAINT pilot_job_input_unique UNIQUE(id,input_version_id);
ALTER TABLE pilot_jobs ADD CONSTRAINT pilot_job_snapshot_unique UNIQUE(id,snapshot_id);
ALTER TABLE pilot_bundle_reports ADD CONSTRAINT pilot_report_job_lineage FOREIGN KEY(job_id,input_version_id) REFERENCES pilot_jobs(id,input_version_id);
ALTER TABLE pilot_bundle_reports ADD CONSTRAINT pilot_report_lineage UNIQUE(id,job_id);
ALTER TABLE pilot_task_analyses ADD CONSTRAINT pilot_analysis_report_lineage FOREIGN KEY(report_id,job_id) REFERENCES pilot_bundle_reports(id,job_id);
ALTER TABLE pilot_analytics_results ADD CONSTRAINT pilot_result_snapshot_lineage FOREIGN KEY(job_id,snapshot_id) REFERENCES pilot_jobs(id,snapshot_id);
ALTER TABLE pilot_attempts ADD CONSTRAINT pilot_attempt_slot_unique UNIQUE(id,job_id,epoch);
ALTER TABLE pilot_slots ADD CONSTRAINT pilot_slot_attempt_lineage FOREIGN KEY(attempt_id,job_id,epoch) REFERENCES pilot_attempts(id,job_id,epoch);
ALTER TABLE pilot_slots ADD CONSTRAINT pilot_slot_complete CHECK((attempt_id IS NULL AND job_id IS NULL AND epoch IS NULL) OR (attempt_id IS NOT NULL AND job_id IS NOT NULL AND epoch IS NOT NULL));
CREATE FUNCTION pilot_same_bundle_photo() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pilot_input_versions v JOIN pilot_photo_assets a ON a.bundle_id=v.bundle_id WHERE v.id=NEW.version_id AND a.id=NEW.photo_id) THEN RAISE EXCEPTION 'photo belongs to another bundle' USING ERRCODE='23503'; END IF; RETURN NEW; END $$;
CREATE TRIGGER pilot_photo_lineage BEFORE INSERT OR UPDATE ON pilot_version_photos FOR EACH ROW EXECUTE FUNCTION pilot_same_bundle_photo();
CREATE FUNCTION pilot_analysis_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.id<>OLD.id OR NEW.task_id<>OLD.task_id OR NEW.job_id<>OLD.job_id OR NEW.report_id<>OLD.report_id OR NEW.analysis IS DISTINCT FROM OLD.analysis THEN RAISE EXCEPTION 'immutable task analysis'; END IF; RETURN NEW; END $$;
CREATE TRIGGER pilot_task_material_immutable BEFORE UPDATE ON pilot_task_analyses FOR EACH ROW EXECUTE FUNCTION pilot_analysis_immutable();
CREATE TRIGGER pilot_ledger_immutable BEFORE UPDATE OR DELETE ON pilot_fund_ledger FOR EACH ROW EXECUTE FUNCTION pilot_immutable();
